create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role text not null default 'editor' check(role in('admin','editor')),created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,description text,published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.product_grades(id uuid primary key default gen_random_uuid(),product_id uuid references public.products(id) on delete cascade,slug text unique not null,name text not null,particle_size_min numeric,particle_size_max numeric,particle_size_unit text default 'mm',packaging text,storage text,safety text,evidence_level text not null default 'Testing required',is_published boolean not null default false);
create table if not exists public.industries(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,description text);
create table if not exists public.applications(id uuid primary key default gen_random_uuid(),industry_id uuid references public.industries(id) on delete set null,slug text unique not null,name text not null,description text,evidence_level text not null default 'Unverified',published boolean not null default false);
create table if not exists public.technical_properties(id uuid primary key default gen_random_uuid(),name text not null,unit text,description text,created_at timestamptz not null default now());
create table if not exists public.specifications(id uuid primary key default gen_random_uuid(),product_grade_id uuid references public.product_grades(id) on delete cascade,property_id uuid references public.technical_properties(id) on delete cascade,value_text text,numeric_value numeric,evidence_level text not null,source_id uuid,is_jyothi_specific boolean not null default false,is_verified boolean not null default false,notes text);
create table if not exists public.research_sources(id uuid primary key default gen_random_uuid(),title text not null,authors text,publisher text,url text,source_date date,source_type text,created_at timestamptz not null default now());
create table if not exists public.research_claims(id uuid primary key default gen_random_uuid(),claim text not null,application_id uuid references public.applications(id) on delete set null,evidence_level text not null,source_id uuid references public.research_sources(id) on delete set null,source_date date,source_type text,is_jyothi_specific boolean not null default false,is_historical boolean not null default false,is_verified boolean not null default false,notes text);
create table if not exists public.documents(id uuid primary key default gen_random_uuid(),title text not null,kind text not null,storage_path text not null,published boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.coa_records(id uuid primary key default gen_random_uuid(),product_grade_id uuid references public.product_grades(id) on delete cascade,batch_reference text,document_id uuid references public.documents(id) on delete set null,issued_at date,verified boolean not null default false);
create table if not exists public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid references public.products(id) on delete cascade,product_grade_id uuid references public.product_grades(id) on delete cascade,storage_path text not null,alt_text text not null,sort_order integer not null default 0,published boolean not null default false);
create table if not exists public.certifications(id uuid primary key default gen_random_uuid(),name text not null,issuer text,document_id uuid references public.documents(id) on delete set null,verified boolean not null default false,published boolean not null default false);
create table if not exists public.contacts(id uuid primary key default gen_random_uuid(),name text not null,company text not null,email text not null,phone text not null,application text not null,grade text not null,quantity text not null,location text not null,message text,source text not null default 'website',status text not null default 'new',created_at timestamptz not null default now());

alter table public.profiles enable row level security;alter table public.products enable row level security;alter table public.product_grades enable row level security;alter table public.industries enable row level security;alter table public.applications enable row level security;alter table public.technical_properties enable row level security;alter table public.specifications enable row level security;alter table public.research_sources enable row level security;alter table public.research_claims enable row level security;alter table public.documents enable row level security;alter table public.coa_records enable row level security;alter table public.product_images enable row level security;alter table public.certifications enable row level security;alter table public.contacts enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
create policy "public published products" on public.products for select using(published=true);create policy "public published grades" on public.product_grades for select using(is_published=true);create policy "public published industries" on public.industries for select using(true);create policy "public published applications" on public.applications for select using(published=true);create policy "public published research sources" on public.research_sources for select using(true);create policy "public published claims" on public.research_claims for select using(is_verified=true);create policy "public published documents" on public.documents for select using(published=true);create policy "public published images" on public.product_images for select using(published=true);create policy "public published certifications" on public.certifications for select using(published=true);
create policy "admins manage profiles" on public.profiles for all using(public.is_admin()) with check(public.is_admin());create policy "admins manage products" on public.products for all using(public.is_admin()) with check(public.is_admin());create policy "admins manage grades" on public.product_grades for all using(public.is_admin()) with check(public.is_admin());create policy "admins manage industries" on public.industries for all using(public.is_admin()) with check(public.is_admin());create policy "admins manage applications" on public.applications for all using(public.is_admin()) with check(public.is_admin());create policy "admins manage technical" on public.technical_properties for all using(public.is_admin()) with check(public.is_admin());create policy "admins manage specifications" on public.specifications for all using(public.is_admin()) with check(public.is_admin());create policy "admins manage research sources" on public.research_sources for all using(public.is_admin()) with check(public.is_admin());create policy "admins manage research claims" on public.research_claims for all using(public.is_admin()) with check(public.is_admin());create policy "admins manage documents" on public.documents for all using(public.is_admin()) with check(public.is_admin());create policy "admins manage coa" on public.coa_records for all using(public.is_admin()) with check(public.is_admin());create policy "admins manage images" on public.product_images for all using(public.is_admin()) with check(public.is_admin());create policy "admins manage certifications" on public.certifications for all using(public.is_admin()) with check(public.is_admin());create policy "public submit contact" on public.contacts for insert with check(true);create policy "admins read contacts" on public.contacts for select using(public.is_admin());create policy "admins update contacts" on public.contacts for update using(public.is_admin()) with check(public.is_admin());
insert into public.industries(slug,name,description) values('horticulture','Horticulture','Growing-media and propagation applications.'),('agriculture','Agriculture','Soil and formulation applications.'),('construction','Construction','Lightweight and insulation formulations.'),('industrial','Industrial','Manufacturing applications pending qualification.'),('insulation','Insulation','Thermal and fire-oriented applications.'),('other','Other','Future application category.') on conflict(slug) do nothing;
